### Python

```python
import sys

def solve() -> None:
    data = sys.stdin.read().split()
    it = iter(data)
    t = int(next(it))
    out_lines = []
    for _ in range(t):
        n = int(next(it))
        e = [int(next(it)) for _ in range(n)]
        if n == 1:
            out_lines.append(str(e[0]))
            continue
        if n >= 3:
            pos_sum = sum(x for x in e if x > 0)
            out_lines.append(str(pos_sum * n))
            continue
        # n == 2
        if e[0] < 0:
            temp = max(0, e[0] + e[1])
            out_lines.append(str(temp * 2))
        else:
            if e[1] >= 0:
                out_lines.append(str((e[0] + e[1]) * 2))
            else:
                out_lines.append(str(e[0] * 2))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
```

### Java

```java
import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int T = Integer.parseInt(br.readLine());
        StringBuilder sb = new StringBuilder();
        while (T-- > 0) {
            int n = Integer.parseInt(br.readLine());
            int[] e = new int[n];
            StringTokenizer st = new StringTokenizer(br.readLine());
            for (int i = 0; i < n; i++) {
                e[i] = Integer.parseInt(st.nextToken());
            }
            if (n == 1) {
                sb.append(e[0]).append("\n");
                continue;
            }
            if (n >= 3) {
                long posSum = 0;
                for (int x : e) {
                    if (x > 0) posSum += x;
                }
                sb.append(posSum * n).append("\n");
                continue;
            }
            // n == 2
            if (e[0] < 0) {
                long temp = Math.max(0, e[0] + e[1]);
                sb.append(temp * 2).append("\n");
            } else {
                if (e[1] >= 0) {
                    sb.append((e[0] + e[1]) * 2L).append("\n");
                } else {
                    sb.append(e[0] * 2L).append("\n");
                }
            }
        }
        System.out.print(sb);
    }
}
